"""Does the LLM judge favour traces generated by its own model family?

Reviewer KLd3 (INLG 2026): "chosen_conf (the 7th feature) is produced by Gemini
3 Flash, which is also one of the seven evaluated models. The paper validates
judge quality via agreement with a blinded human and other judge families ...
but I got the sense that these are aggregate agreement checks and wouldn't
detect self-preference bias ... specific to Gemini 3 Flash rating its own
traces."

Two tests, both on data already collected.

TEST A (well powered, confounded). Per generating model, how well does the
judge's chosen-candidate confidence discriminate correct from wrong answers, and
how high does it score wrong answers? Self-preference inflates the judge's score
on its OWN wrong answers, which depresses discrimination for that model and
raises its mean score on wrong traces. Confound: Flash's traces may genuinely be
easier to judge, so a difference here is suggestive rather than conclusive.

TEST B (clean, underpowered). On the 75 gold traces that a second judge family
(DeepSeek V3) also scored, compare Gemini's score against DeepSeek's on the SAME
trace. Trace properties cancel, because both judges read identical text.
Self-preference predicts a larger Gemini-minus-DeepSeek gap on Flash traces than
on the rest. Only 11 of the 75 are Flash, so this is directional only.

    .venv-x64/Scripts/python.exe llm_evaluation/datasets/_judge_self_preference.py

Ported from the working repository for the public release. Paths resolve through
_paths.py against data/ in this bundle; the analysis itself is unchanged.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np
import pandas as pd
from sklearn.metrics import average_precision_score, roc_auc_score

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
sys.path.insert(0, str(Path(__file__).resolve().parent))
from _paths import (PAPER, JUDGE_DIR, AUDIT, EFFORT, DOMAINS, GEMINI_FAMILY,
                    JUDGE_MODEL, SECOND_JUDGE_EXTENDED, selection_puzzles,
                    load_traces_with_features, chosen_conf_table)

HERE = Path(__file__).resolve().parent

JUDGE_MODEL = "Gemini 3 Flash"
N_BOOT = 2000
SEED = 42

def load_chosen() -> pd.DataFrame:
    """Chosen-candidate judge scores for all four domains."""
    rc = pd.read_csv(JUDGE_DIR / "eureka_judge_full.csv")
    rc = rc[rc.is_chosen == 1].dropna(subset=["judge_confidence"]).copy()
    rc["chosen_conf"] = rc.judge_confidence

    vp = pd.read_csv(JUDGE_DIR / "eureka_judge_vp.csv")
    vp = vp[(vp.is_chosen == 1) & (vp.pass_type == "un_augmented")].dropna(
        subset=["judge_confidence"]).copy()
    vp["chosen_conf"] = vp.judge_confidence

    cp = pd.read_csv(JUDGE_DIR / "eureka_judge_connp.csv")
    cp = cp[cp.error.isna()].copy()

    def mean_agg(gs):
        if pd.isna(gs):
            return None
        try:
            vals = [s for s in json.loads(gs) if isinstance(s, (int, float))]
        except Exception:
            return None
        return sum(vals) / len(vals) if vals else None

    cp["chosen_conf"] = [mean_agg(g) for g in cp.group_scores]
    cp["domain"] = "ConnectionsPlus"
    cp = cp.dropna(subset=["chosen_conf"])

    cols = ["model", "domain", "puzzle_id", "correct", "chosen_conf"]
    df = pd.concat([rc[cols], vp[cols], cp[cols]], ignore_index=True)
    df["correct"] = df["correct"].astype(int)
    return df

def test_a(df: pd.DataFrame) -> None:
    print("=" * 96)
    print("TEST A  Per-generating-model behaviour of the judge (n = %d)" % len(df))
    print("=" * 96)
    print(f"{'generating model':<26}{'n':>6}{'base':>7}{'AP':>8}{'AUC':>7}"
          f"{'mean conf':>11}{'on wrong':>10}{'on right':>10}")
    print("-" * 96)
    rows = []
    for m, g in df.groupby("model"):
        if g.correct.nunique() < 2:
            continue
        ap = average_precision_score(g.correct, g.chosen_conf)
        auc = roc_auc_score(g.correct, g.chosen_conf)
        w = g.loc[g.correct == 0, "chosen_conf"].mean()
        r = g.loc[g.correct == 1, "chosen_conf"].mean()
        rows.append((m, len(g), g.correct.mean(), ap, auc, g.chosen_conf.mean(), w, r))
    for m, n, base, ap, auc, mc, w, r in sorted(rows, key=lambda x: -x[4]):
        star = "  <- the judge" if m == JUDGE_MODEL else ""
        print(f"{m:<26}{n:>6}{base:>7.3f}{ap:>8.3f}{auc:>7.3f}{mc:>11.1f}{w:>10.1f}{r:>10.1f}{star}")

    judge = [r for r in rows if r[0] == JUDGE_MODEL][0]
    others = [r for r in rows if r[0] != JUDGE_MODEL]
    print()
    print(f"  {JUDGE_MODEL} AUC {judge[4]:.3f} vs others {np.mean([o[4] for o in others]):.3f} "
          f"(range {min(o[4] for o in others):.3f} to {max(o[4] for o in others):.3f})")
    print(f"  {JUDGE_MODEL} mean confidence on WRONG answers {judge[6]:.1f} vs others "
          f"{np.mean([o[6] for o in others]):.1f} "
          f"(range {min(o[6] for o in others):.1f} to {max(o[6] for o in others):.1f})")
    print("\n  Self-preference would show as the judge's own row having the LOWEST AUC and the")
    print("  HIGHEST mean confidence on wrong answers. Confounded: Flash's traces may simply be")
    print("  easier to judge.")

def test_b() -> None:
    """Gemini vs DeepSeek on identical traces. Trace properties cancel."""
    print()
    print("=" * 96)
    print("TEST B  Gemini minus DeepSeek on the same trace (gold sample)")
    print("=" * 96)
    sample = json.loads((AUDIT / "sample.json").read_text(encoding="utf-8"))
    model_of = {t["trace_id"]: t["model"] for t in sample["traces"]}
    gold = json.loads((AUDIT / "gold_key.json").read_text(encoding="utf-8"))
    ds = json.loads((AUDIT / "second_judge_deepseek_deepseek-chat.json").read_text(
        encoding="utf-8"))["results"]

    # Fold in the extended pass (350 further traces, 50 per generating model).
    ext_path = SECOND_JUDGE_EXTENDED
    ext_scores, ext_model = {}, {}
    if ext_path.exists():
        for line in ext_path.read_text(encoding="utf-8").splitlines():
            try:
                r = json.loads(line)
            except Exception:
                continue
            ext_scores[r["trace_id"]] = {"scores": r["scores"]}
            ext_model[r["trace_id"]] = r["model"]
    ds = {**ds, **ext_scores}
    model_of = {**model_of, **ext_model}

    # Gemini's scores for the extended traces come from the judge CSVs.
    gemini_ext = {}
    if ext_scores:
        frames = []
        rc = pd.read_csv(JUDGE_DIR / "eureka_judge_full.csv")
        rc["pass_type"] = "un_augmented"
        frames.append(rc)
        vp = pd.read_csv(JUDGE_DIR / "eureka_judge_vp.csv")
        frames.append(vp[vp.pass_type == "un_augmented"])
        j = pd.concat(frames, ignore_index=True).dropna(subset=["candidate"])
        j["puzzle_id"] = j.puzzle_id.astype(str)
        j["trace_id"] = j.domain + "|" + j.model + "|" + j.puzzle_id + "|" + j.pass_type
        j = j[j.trace_id.isin(ext_scores)]
        for tid, g in j.groupby("trace_id"):
            gemini_ext[tid] = {"candidates": {
                r.candidate: {"judge_confidence": r.judge_confidence,
                              "is_chosen": int(r.is_chosen)}
                for r in g.itertuples() if pd.notna(r.judge_confidence)}}
    gold = {**gold, **gemini_ext}

    chosen, allcand = [], []
    for tid, rec in gold.items():
        if tid not in ds or tid not in model_of:
            continue
        scores = ds[tid].get("scores", {})
        for cand, info in rec.get("candidates", {}).items():
            g = info.get("judge_confidence")
            d = scores.get(cand)
            if g is None or d is None:
                continue
            row = {"trace_id": tid, "model": model_of[tid], "candidate": cand,
                   "gemini": float(g), "deepseek": float(d),
                   "is_chosen": int(info.get("is_chosen", 0))}
            allcand.append(row)
            if row["is_chosen"]:
                chosen.append(row)

    for label, rows, cluster in (("committed answer only", chosen, False),
                                 ("all candidates", allcand, True)):
        if not rows:
            print(f"  {label}: no rows aligned")
            continue
        d = pd.DataFrame(rows)
        d["delta"] = d.gemini - d.deepseek
        own, oth = d[d.model == JUDGE_MODEL], d[d.model != JUDGE_MODEL]
        diff = own.delta.mean() - oth.delta.mean()
        print()
        print(f"  {label}: n={len(d)}  ({JUDGE_MODEL} {len(own)}, others {len(oth)}; "
              f"{d.trace_id.nunique()} traces)")
        print(f"    traces written by {JUDGE_MODEL} ({len(own):>3}): "
              f"Gemini scores {own.delta.mean():+.2f} vs DeepSeek V3")
        print(f"    traces written by the other 6 models ({len(oth):>3}): "
              f"Gemini scores {oth.delta.mean():+.2f} vs DeepSeek V3")
        print(f"    difference (own minus other)     : {diff:+.2f}")

        rng = np.random.default_rng(SEED)
        boots = []
        if cluster:
            own_t = own.trace_id.unique()
            oth_t = oth.trace_id.unique()
            by_t = {k: v.delta.values for k, v in d.groupby("trace_id")}
            for _ in range(N_BOOT):
                a = np.concatenate([by_t[x] for x in rng.choice(own_t, len(own_t))])
                b = np.concatenate([by_t[x] for x in rng.choice(oth_t, len(oth_t))])
                boots.append(a.mean() - b.mean())
        else:
            for _ in range(N_BOOT):
                a = own.delta.values[rng.integers(0, len(own), len(own))]
                b = oth.delta.values[rng.integers(0, len(oth), len(oth))]
                boots.append(a.mean() - b.mean())
        lo, hi = np.percentile(boots, [2.5, 97.5])
        print(f"    95% CI{' (trace-clustered)' if cluster else '':<19}: [{lo:+.2f}, {hi:+.2f}]")

    print()
    print("  Self-preference predicts a POSITIVE difference: Gemini scoring its own traces higher")
    print("  than DeepSeek does, relative to how the two judges differ on other models' traces.")

def test_c() -> None:
    """Both LLM judges measured against the human, on identical traces.

    The human is a neutral referee: it is not the judge and not one of the
    evaluated models. Self-preference predicts that Gemini sits further above
    the human on its OWN traces than on other models' traces. DeepSeek provides
    the control: if it shows the same pattern, the effect belongs to Flash's
    traces (they read as more confident) rather than to Gemini judging itself.
    """
    print()
    print("=" * 96)
    print("TEST C  Both judges vs the human referee, same traces (difference in differences)")
    print("=" * 96)
    sample = json.loads((AUDIT / "sample.json").read_text(encoding="utf-8"))
    model_of = {t["trace_id"]: t["model"] for t in sample["traces"]}
    gold = json.loads((AUDIT / "gold_key.json").read_text(encoding="utf-8"))
    human = json.loads((AUDIT / "annotations.json").read_text(encoding="utf-8"))
    ds = json.loads((AUDIT / "second_judge_deepseek_deepseek-chat.json").read_text(
        encoding="utf-8"))["results"]

    rows = []
    for tid, rec in gold.items():
        if tid not in model_of or tid not in human:
            continue
        h_scores = human[tid].get("scores", {})
        d_scores = ds.get(tid, {}).get("scores", {})
        for cand, info in rec.get("candidates", {}).items():
            g, h, d = info.get("judge_confidence"), h_scores.get(cand), d_scores.get(cand)
            if g is None or h is None:
                continue
            rows.append({"trace_id": tid, "model": model_of[tid], "candidate": cand,
                         "is_chosen": int(info.get("is_chosen", 0)),
                         "gemini": float(g), "human": float(h),
                         "deepseek": float(d) if d is not None else np.nan})

    d = pd.DataFrame(rows)
    d["G_minus_H"] = d.gemini - d.human
    d["D_minus_H"] = d.deepseek - d.human

    rng = np.random.default_rng(SEED)

    def clustered_ci(frame, col):
        own_t = frame.loc[frame.model == JUDGE_MODEL, "trace_id"].unique()
        oth_t = frame.loc[frame.model != JUDGE_MODEL, "trace_id"].unique()
        by_t = {k: v[col].dropna().values for k, v in frame.groupby("trace_id")}
        boots = []
        for _ in range(N_BOOT):
            a = np.concatenate([by_t[x] for x in rng.choice(own_t, len(own_t))])
            b = np.concatenate([by_t[x] for x in rng.choice(oth_t, len(oth_t))])
            if len(a) and len(b):
                boots.append(a.mean() - b.mean())
        return np.percentile(boots, [2.5, 97.5])

    for label, subset in (("committed answer only", d[d.is_chosen == 1]), ("all candidates", d)):
        print(f"\n  {label}: {len(subset)} rows over {subset.trace_id.nunique()} traces "
              f"({JUDGE_MODEL} {int((subset.model == JUDGE_MODEL).sum())})")
        print(f"    {'judge minus human':<26}{'own traces':>12}{'other traces':>14}"
              f"{'difference':>12}{'95% CI':>20}")
        results = {}
        for col, name in (("G_minus_H", "Gemini (the judge)"), ("D_minus_H", "DeepSeek (control)")):
            s = subset.dropna(subset=[col])
            own = s.loc[s.model == JUDGE_MODEL, col]
            oth = s.loc[s.model != JUDGE_MODEL, col]
            if len(own) == 0 or len(oth) == 0:
                continue
            diff = own.mean() - oth.mean()
            lo, hi = clustered_ci(s, col)
            results[col] = diff
            print(f"    {name:<26}{own.mean():>+12.2f}{oth.mean():>+14.2f}{diff:>+12.2f}"
                  f"{f'[{lo:+.2f}, {hi:+.2f}]':>20}")
        if len(results) == 2:
            did = results["G_minus_H"] - results["D_minus_H"]
            print(f"    {'difference in differences':<26}{'':>12}{'':>14}{did:>+12.2f}")

    print("\n  Self-preference predicts Gemini sitting further above the human on its own traces")
    print("  (a positive difference) while DeepSeek does not. If both judges show the same")
    print("  pattern, the effect is a property of Flash's traces, not of Gemini judging itself.")
    print("\n  Caveat: the human labeller saw the generating model's name in the annotation UI,")
    print("  though not the judge's scores, the emitted answer, the puzzle or the ground truth.")

def main():
    df = load_chosen()
    test_a(df)
    test_b()
    test_c()

if __name__ == "__main__":
    main()
